import { defineStore } from 'pinia'
import { createResource } from 'frappe-ui'
import { reactive, ref } from 'vue'
import { sessionStore } from './session'
import { getSettings } from './settings'

export const viewsStore = defineStore('crm-views', () => {
  const session = sessionStore()
  const canReadViews = getSettings().settings.value.can_read_crm_view_settings
  let viewsByName = reactive({})
  let pinnedViews = ref([])
  let publicViews = ref([])
  let standardViews = ref({})
  const defaultView = ref(null)

  // Views
  const views = createResource({
    url: 'frappe.client.get_list',
    params: {
      doctype: 'CRM View Settings',
      filters: [['user', 'in', ['', session.user]]],
      fields: [
        'name',
        'label',
        'icon',
        'user',
        'is_standard',
        'is_default',
        'type',
        'dt',
        'route_name',
        'pinned',
        'public',
        'filters',
        'order_by',
        'load_default_columns',
        'columns',
        'rows',
        'group_by_field',
        'column_field',
        'title_field',
        'kanban_columns',
        'kanban_fields',
      ],
      limit_page_length: 500,
    },
    cache: canReadViews ? 'crm-views' : undefined,
    initialData: [],
    auto: canReadViews,
    transform(views) {
      pinnedViews.value = []
      publicViews.value = []
      defaultView.value = null
      for (let view of views) {
        viewsByName[view.name] = view
        view.type = view.type || 'list'
        if (view.pinned) {
          pinnedViews.value?.push(view)
        }
        if (view.public) {
          publicViews.value?.push(view)
        }
        if (view.is_standard && view.dt) {
          standardViews.value[view.dt + ' ' + view.type] = view
        }
        if (view.is_default) {
          defaultView.value = view
        }
      }
      return views
    },
  })

  function getDefaultView() {
    return defaultView.value
  }

  function getView(view, type, doctype = null) {
    type = type || 'list'
    if (!view && doctype) {
      return standardViews.value[doctype + ' ' + type] || null
    }
    return viewsByName[view]
  }

  function getPinnedViews() {
    if (!pinnedViews.value?.length) return []
    return pinnedViews.value
  }

  function getPublicViews() {
    if (!publicViews.value?.length) return []
    return publicViews.value
  }

  async function reload() {
    if (canReadViews) await views.reload()
  }

  return {
    views,
    defaultView,
    standardViews,
    getDefaultView,
    getPinnedViews,
    getPublicViews,
    reload,
    getView,
  }
})
